  if(n===1){var s=sg[0],q=function(k){return dn.querySelector(k)};if(q('.t'))q('.t').textContent=s.t;if(q('.te'))q('.te').textContent=s.te||'';if(q('.nmz'))q('.nmz').textContent=s.n;if(q('.nme'))q('.nme').textContent=s.ne||'';var im=q('.im img');if(im)im.setAttribute('src',imgOf(s.img));}
