/* ---------------- 9) محرك التقييم الآلي للبرامج الجديدة (من تسليمات الاختبارات) ---------------- */
function gradeFrom(score){var b=gradeOf39(score);return{score:Math.round(score*100)/100,gl:b[1],pts:b[2],ok:b[2]>=2}}
V5.gradeFrom=gradeFrom;
function reconcileExams(){var ch=0;(S.subs||[]).forEach(function(b){if(b.max65)return;/* v73: اختبارات البنوك تُرصد عند التسليم بعدد الأسئلة المسحوبة */var e=(S.exams||[]).find(function(x){return x.id==b.eid});if(!e||!e.courseId||e.pl||e.placement)return;
 var p=courseProg(e.courseId);if(!p||p.id==DIP)return;var s=S.students.find(function(x){return x.id==b.sid});if(!s)return;
 s.gr=s.gr||{};var old=s.gr[e.courseId];if(old&&old.man)return;if(old&&old.src==='exam51'&&old.sub==b.id&&old.tot===b.total)return;
 var n=(e.q||[]).length||+b.max||0;if(!n)return;var hasW=(e.q||[]).some(function(q){return q.ty=='wr'}),graded=b.st==='مُقيَّم'||b.st==='معتمد'||b.st==='تم الاعتماد والنشر'||!hasW;
 var pct=Math.min(100,Math.max(0,(+b.total||0)/n*100)),g=gradeFrom(Math.round(pct)),thr=+e.passPct||60;
 s.gr[e.courseId]={rel:1,score:g.score,gl:g.gl,pts:g.pts,ok:pct>=thr,fin:graded?1:0,prov:graded?0:1,src:'exam51',sub:b.id,tot:b.total,eid:e.id,date:TODAY()};
 if((s.reg||[]).indexOf(e.courseId)<0)s.reg=(s.reg||[]).concat([e.courseId]);ch++;
 aud(L('رصد آلي فوري لدرجة اختبار','Instant automatic exam grading'),s.id,(p.name||'')+' · '+e.courseId+' · '+Math.round(pct)+'%')});return ch}
V5.reconcileExams=reconcileExams;

/* ---------------- 10) اكتمال متطلبات البرنامج + الإصدار التلقائي للوثائق ---------------- */
var docOn=function(t){var d=(S.v51.docs||{})[t];return !(d&&d.on===false)};V5.docOn=docOn;
function pconf(p,t){var e=p.eng||(p.eng={}),D=e.docs||(e.docs={});if(!D[t]){D[t]=p.id==DIP?({gtr:{auto:1},dgrad:{auto:1},acc:{auto:0}}[t]||{auto:0}):({ggrad:{auto:1},gtr:{auto:1},acc:{auto:1}}[t]||{auto:0})}return D[t]}
V5.pconf=pconf;
function complete(s,p){if(!s||!p)return{ok:0,why:'—'};var e=p.eng||{},G=e.grad||{};
 if(p.id==DIP){if(typeof W.gradElig!=='function')return{ok:0,why:'—'};var r=W.gradElig(s);if(r.ok||/صدرت له وثيقة تخرج/.test(r.why||''))return{ok:1,gpa:calc(s).gpa,hours:calc(s).E};return r}
 if(!stuIn(s,p.id))return{ok:0,why:L('غير مقيّد في هذا البرنامج','Not enrolled in this programme')};
 if(G.needStatus&&en112St(s,p.id)!=='متخرج')return{ok:0,why:L('لم تُعتمد حالة التخرج في هذا البرنامج','Graduation status not approved in this programme')};
 var Cs=pCourses(p);if(!Cs.length)return{ok:0,why:L('لا توجد مقررات','No courses')};
 var req=(G.mandatory&&G.mandatory.length)?Cs.filter(function(c){return G.mandatory.indexOf(c.id)>-1}):Cs.filter(function(c){return c.type!=='اختياري'});
 var miss=req.filter(function(c){var g=(s.gr||{})[c.id];return !(g&&g.fin&&g.ok)});if(miss.length)return{ok:0,why:L('مقررات غير مجتازة: ','Courses not passed: ')+miss.length};
 var k=calcP(s,p);if(G.hours&&k.E<+G.hours)return{ok:0,why:L('الساعات المجتازة ','Earned hours ')+k.E+' / '+G.hours};
 if(G.minGpa&&(k.gpa||0)<+G.minGpa)return{ok:0,why:L('المعدل أقل من ','GPA below ')+G.minGpa};
 return{ok:1,gpa:k.gpa,hours:k.E}}
V5.complete=complete;
var hasDoc=function(s,p,t){return S.certs.some(function(c){return c.sid==s.id&&c.type==t&&!c.revoked&&(t==='dgrad'||c.prog==p.id)})};
/* v52: تأكيد قبل الإصدار — في وضع المراجعة تُوضع الوثيقة في قائمة انتظار الاعتماد بدل إصدارها */
var qKey=function(t,sid,pid){return t+'|'+sid+'|'+pid};V5.qKey=qKey;
