async function hashPw(pw,salt){var t=salt+'|'+pw;try{if(W.crypto&&crypto.subtle){var b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return Array.from(new Uint8Array(b)).map(function(x){return x.toString(16).padStart(2,'0')}).join('')}}catch(e){}
 return 'f'+fnv(t)+fnv(t.split('').reverse().join(''))}
V5.hashPw=hashPw;
async function memberLogin(u,p){u=String(u||'').trim();var m=live(S.v51.members).find(function(x){return x.user&&x.user.toLowerCase()===u.toLowerCase()&&x.active!==0});if(!m||!m.hash)return null;
 var un=unit(m.unitId);if(!un||un.deleted||un.portalOff)return null;if(await hashPw(p,m.salt)!==m.hash)return null;return m}
