  if(typeof sb!=='undefined'&&sb&&m.acct){try{var em=(await sb.rpc('login_email',{ident:m.user})).data;if(em){var r=await sb.auth.signInWithPassword({email:em,password:v.p});if(!r.error){V5.staffSb=1}}}catch(e){}}
