/* ---------------- 13) حماية الحذف (Zero-Deletion Guard) + سلة المحذوفات ---------------- */
function softDel(o,kind,why){o.deleted={at:NOW(),by:who(),why:why||''};touch(o);aud(L('حذف منطقي (قابل للاسترجاع)','Soft delete (restorable)'),kind+':'+(o.id||''),why||'')}
