V5.softDel=softDel;V5.restoreObj=restoreObj;
function linksOf(kind,o){var n=[];
 if(kind==='program'){var st=S.students.filter(function(s){return stuIn(s,o.id)}).length,rq=S.requests.filter(function(r){return r.prog==o.id}).length,ce=S.certs.filter(function(c){return c.prog==o.id}).length;if(st)n.push(st+L(' طالب',' student(s)'));if(rq)n.push(rq+L(' طلب',' request(s)'));if(ce)n.push(ce+L(' وثيقة صادرة',' issued document(s)'))}
 if(kind==='course'){var a=S.students.filter(function(s){return (s.reg||[]).indexOf(o.id)>-1||(s.gr||{})[o.id]}).length,b=(S.subs||[]).filter(function(x){var e=(S.exams||[]).find(function(y){return y.id==x.eid});return e&&e.courseId==o.id}).length;if(a)n.push(a+L(' طالب مسجّل/مرصود',' registered/graded student(s)'));if(b)n.push(b+L(' تسليم اختبار',' exam submission(s)'))}
 if(kind==='unit'){var m=live(S.v51.members).filter(function(x){return x.unitId==o.id}).length,c=live(S.v51.units).filter(function(x){return x.parent==o.id}).length,pp=engProgs().filter(function(p){return p.eng&&p.eng.unitId==o.id}).length,ps=live(S.v51.positions).filter(function(x){return x.unitId==o.id}).length;if(o.locked)n.push(L('جهة أساسية','core unit'));if(m)n.push(m+L(' عضو',' member(s)'));if(c)n.push(c+L(' جهة فرعية',' sub-unit(s)'));if(pp)n.push(pp+L(' برنامج',' program(s)'));if(ps)n.push(ps+L(' منصب',' position(s)'))}
 if(kind==='position'||kind==='seal'){var used=S.certs.some(function(c){return c.v51&&(kind==='position'?(c.v51.sg||[]).some(function(s){return s.p==o.id}):false)});if(used)n.push(L('مستخدم في وثائق صادرة','used in issued documents'));if(o.locked)n.push(L('أساسي','core'))}
 if(kind==='sch'){var r=S.requests.filter(function(x){return x.sch==o.id||(x.schDec&&x.schDec.schId==o.id)}).length,s2=S.students.filter(function(x){return x.sch51&&x.sch51.schId==o.id}).length;if(r)n.push(r+L(' طلب منحة',' application(s)'));if(s2)n.push(s2+L(' طالب ممنوح',' holder(s)'))}
 if(kind==='degree'){var d=engProgs().filter(function(p){return p.eng&&p.eng.degree==o.id}).length;if(d)n.push(d+L(' برنامج',' program(s)'))}
 return n}
V5.linksOf=linksOf;
