W.decide=function(id,yes){var r=S.requests.find(function(x){return x.id==id});var res=_dec.apply(this,arguments);
 try{if(yes&&r&&r.sid){var s=S.students.find(function(x){return x.id==r.sid}),p=prog(r.prog);
  if(s&&p&&isEng(p)){if(p.kind==='program'&&s.prog!=p.id)s.prog=p.id;s.en51=s.en51||[];if(!s.en51.some(function(e){return e.pid==p.id}))s.en51.push({pid:p.id,from:TODAY(),admTerm:curTermName()||r.admTerm51||''});
   if(r.schDec&&r.schDec.res!=='reject'&&r.schDec.schId)s.sch51={schId:r.schDec.schId,res:r.schDec.res,from:TODAY()};
   if(docOn('acc')&&pconf(p,'acc').auto&&!S.certs.some(function(c){return c.type==='acc'&&c.sid==s.id&&c.prog==p.id&&!c.revoked})){
    if(p.id==DIP&&typeof W.accMake==='function')W.accMake(id);else{V5.qMode=1;try{baseDoc('acc',s,p,{rid:id,from:p.from||'',adm_mode:'انتظام',adm_term:(s.en51.find(function(e){return e.pid==p.id})||{}).admTerm||'',text:''})}finally{V5.qMode=0}}}
   save()}}}catch(e){console.error('v51 decide',e)}return res};
var _reg=W.reg;
W.reg=function(f){var n=S.requests.length,res=_reg.apply(this,arguments);try{if(S.requests.length>n){var q=S.requests[S.requests.length-1];if(q.prog51){var p=prog(+q.prog51);if(p&&isEng(p))q.prog=p.id}
  if(q.sch){var sc=live(S.v51.sch).find(function(x){return x.id==q.sch});if(!sc||sc.pid!=q.prog){delete q.sch;delete q.schAck}else q.schAt=NOW()}save()}}catch(e){console.error('v51 reg',e)}return res};
function schDecide(rid,res,schId){var r=S.requests.find(function(x){return x.id==rid});if(!r)return;
 if(res==='other'&&!schId){toast(L('اختر المنحة البديلة','Choose the alternative scholarship'));return}
 var dec={res:res,schId:res==='with'?r.sch:res==='other'?schId:'',by:who(),at:NOW()};
 if(res==='reject'){if(r.status!=='مرفوض'){W.decide(rid,0);if(r.status!=='مرفوض')return}}
 else if(r.status!=='مقبول'){W.decide(rid,1);if(r.status!=='مقبول')return}
 r.schDec=dec;var s=r.sid&&S.students.find(function(x){return x.id==r.sid});if(s){if(dec.schId)s.sch51={schId:dec.schId,res:res,from:TODAY()};else delete s.sch51}
 aud(L('قرار منحة','Scholarship decision'),rid,{with:L('قبول مع المنحة المطلوبة','Accepted with requested scholarship'),other:L('قبول مع منحة أخرى','Accepted with another scholarship'),none:L('قبول بدون منحة','Accepted without scholarship'),reject:L('رفض الطلب','Application rejected')}[res]);
 save();go()}
V5.schDecide=schDecide;
var _iss=W.issue;if(typeof _iss==='function')W.issue=function(f){var v=fv(f);if(v.type&&!docOn(v.type)){toast(L('هذا النوع من الوثائق موقوف من «محرك الوثائق».','This document type is disabled in the Documents engine.'));return false}return _iss.apply(this,arguments)};

