var _exS=W.exStud;if(typeof _exS==='function')W.exStud=function(s){if(!perm('st.exams','students'))return '<h3>'+L('الاختبارات المتاحة','Available exams')+'</h3><div class="box"><p class="mu">'+L('هذه الخدمة غير متاحة حالياً.','This service is currently unavailable.')+'</p></div>';
 var all=S.exams;try{S.exams=all.filter(function(e){if(!e.courseId)return true;var p=courseProg(e.courseId);return !p||stuIn(s,p.id)||(p.id==DIP&&+s.prog===DIP)});return _exS.apply(this,arguments)}finally{S.exams=all}};
var _rp=W.reqPanel;if(typeof _rp==='function')W.reqPanel=function(role){if(!perm(role==='student'?'st.docreq':'tf.docreq',role==='student'?'students':'faculty'))return '<h3>'+L('طلب وثيقة','Request a document')+'</h3><div class="box"><p class="mu">'+L('خدمة طلب الوثائق غير متاحة حالياً.','Document requests are currently unavailable.')+'</p></div>';return _rp.apply(this,arguments)};
