var H=V5.h={},U=V5.ui=V5.ui||{pid:null,ps:'info',uid:null,dt:null,sid:null,pos:null,occ:null,sch:null};
var en=function(){return typeof LG!=='undefined'&&LG==='en'};
var fld=function(l,h,full){return '<label'+(full?' style="grid-column:1/-1"':'')+'>'+l+h+'</label>'};
var inp=function(n,v,a){return '<input name="'+n+'" value="'+E(v==null?'':v)+'" '+(a||'')+'>'};
var ta=function(n,v,r){return '<textarea name="'+n+'" rows="'+(r||2)+'">'+E(v||'')+'</textarea>'};
var sel=function(n,o,c,a){return '<select name="'+n+'" '+(a||'')+'>'+o.map(function(x){return '<option value="'+E(x[0])+'"'+(String(x[0])===String(c==null?'':c)?' selected':'')+'>'+E(x[1])+'</option>'}).join('')+'</select>'};
var chk=function(n,on,l){return '<label class="v51ck"><input type="checkbox" name="'+n+'" value="1" '+(on?'checked':'')+'> '+l+'</label>'};
var bt=function(t,oc,c){return '<button type="button" class="btn '+(c||'s')+'" onclick="'+oc+'">'+t+'</button>'};
var T=function(h,rows,cls){return '<div class="tw"><table class="v51t '+(cls||'')+'"><tr>'+h.map(function(x){return '<th>'+x+'</th>'}).join('')+'</tr>'+(rows.join('')||'<tr><td colspan="'+h.length+'" class="mu">'+L('لا توجد بيانات','No data')+'</td></tr>')+'</table></div>'};
var Q=function(s){return String(s).replace(/'/g,"\\'")};
var fvc=function(f){var o=fv(f);f.querySelectorAll('input[type=checkbox][name]').forEach(function(c){o[c.name]=c.checked?1:0});return o};
var done=function(msg){if(msg)flash=msg;save();go()};
var uOpts=function(types,blank){var o=blank?[['',blank]]:[];live(S.v51.units).filter(function(u){return !types||types.indexOf(u.type)>-1}).forEach(function(u){o.push([u.id,en()?(u.nameEn||u.nameAr):u.nameAr])});return o};
var degOpts=function(){return live(S.v51.degrees).sort(function(a,b){return (a.ord||0)-(b.ord||0)}).map(function(d){return [d.id,en()?(d.en||d.ar):d.ar]})};
var lvW=function(e){var w=(e&&e.lvlWord)||'المستوى';return en()?({'المستوى':'Level','الفصل الدراسي':'Semester','السنة الدراسية':'Year'}[w]||'Level'):w};V5.lvW=lvW;
var pName=function(p){return en()?((p.eng&&p.eng.nameEn)||p.name):p.name};
var banner=function(){var m=Object.keys(S.v51.sync.missing||{});return m.length?'<div class="msg er">'+L('تعمل وحدات v51 محلياً وتُحفظ في المتصفح، لكن جداولها غير موجودة في Supabase بعد: ','v51 modules work locally and are saved in the browser, but their tables do not exist in Supabase yet: ')+'<code dir="ltr">'+m.join(', ')+'</code>. '+L('شغّل سكربت الترحيل v51-schema.sql ثم «مزامنة الآن».','Run the v51-schema.sql migration, then “Sync now”.')+'</div>':''};

