H.addPos=function(f){var v=fv(f);S.v51.positions.push(touch({id:RID('pos'),titleAr:v.titleAr,titleEn:v.titleEn,unitId:v.unitId,occ:[]}));aud(L('إضافة منصب','Position added'),v.titleAr,'');done();return false};
H.savePos=function(f){var p=posById(U.pos),v=fv(f);if(!p)return false;p.titleAr=v.titleAr;p.titleEn=v.titleEn;p.unitId=v.unitId;touch(p);aud(L('تعديل منصب','Position edited'),p.id,p.titleAr);done(L('حُفظ المنصب، وانعكس على جميع الوثائق بما فيها الصادرة سابقاً.','Position saved; applied to all documents, including earlier ones.'));return false};
