function openReg(P,now){now=now||Date.now();if(!P||P.deleted)return L('البرنامج غير متاح','Program not available');if(+P.selfReg===0)return L('التسجيل الذاتي غير متاح لهذا البرنامج؛ يتولى المعهد تسجيل المشاركين.','Self-registration is not available for this program; the Institute registers participants.');var t=function(x){return C6.toMs(x,P.tzOff,0)};
 if(P.regFrom&&now<t(P.regFrom))return L('لم يبدأ التسجيل بعد','Registration has not opened yet');if(P.regTo&&now>t(P.regTo))return L('انتهت فترة التسجيل','Registration has closed');if(C6.ended(P,now))return L('انتهى البرنامج','The program has ended');if(!cap(P))return L('اكتمل العدد','The program is full');return ''}
