 V5.imp64={kind:kind,id:o.id,name:o.name||'',at:Date.now(),tab:typeof tab!=='undefined'?tab:'req',snap:JSON.parse(JSON.stringify(o)),dr:(S.docReqs||[]).filter(function(x){return x.uid==o.id}).length,n:0};
