 try{audit4(L('بدء الدخول إلى بوابة صاحب الحساب (الإدارة المركزية)','Central administration opened the account holder’s portal'),o.id,(o.name||'')+' · '+L(KN[kind][0],KN[kind][1]))}catch(e){}
 last=Date.now();flash='';
 if(kind==='s'){me={r:'student',id:o.id};location.hash='#/student'}
