var DEF={bg1:'#FBFCFC',bg2:'#E6ECEE',bar:'#14284B',text:'#1E2A33',label:'#5A6B7B',s:'#14284B',f:'#7D8B95',a:'#3E5C76',g:'#5F7FA0',seal:0,expFS:'year',expMonths:12};
