/* ---------- قياس النص للتصغير التلقائي ---------- */
var CV=null;function tw(t,px,fam,wt){try{CV=CV||document.createElement('canvas').getContext('2d');CV.font=(wt||400)+' '+px+'px "'+fam+'", serif';return CV.measureText(String(t)).width*(fam===EN?1.08:1.04)}catch(e){return String(t).length*px*.5}}
var AR='Noto Naskh Arabic',EN='Tinos';
/* أكبر حجم (بين max وmin) يجعل النص في سطر واحد ضمن العرض؛ وإلا يُلتف عند الحد الأدنى */
/* قياس نص مزدوج: الجزء العربي بالخط العربي والإنجليزي بخطه */
function fit2(ar,en,max,min,w,wt){w-=8;for(var p=max;p>=min;p-=0.25){var x=(ar?tw(ar,p,AR,wt||500)+tw(' / ',p,AR,400):0)+tw(en,p,EN,wt===700?700:400);if(x<=w)return {px:p,wrap:0}}return {px:min,wrap:1}}
