/* ---------- 3) حماية رفع الملفات: النوع الحقيقي والحجم قبل القبول، وتنظيف SVG ---------- */
var SIG={png:[0x89,0x50,0x4E,0x47],jpg:[0xFF,0xD8,0xFF],gif:[0x47,0x49,0x46,0x38],webp:[0x52,0x49,0x46,0x46],pdf:[0x25,0x50,0x44,0x46],zip:[0x50,0x4B,0x03,0x04],ole:[0xD0,0xCF,0x11,0xE0]};
var MAXB={image:5*1048576,svg:1048576,sheet:10*1048576,json:25*1048576,csv:10*1048576,pdf:10*1048576};
function kindOf(f){var n=String(f.name||'').toLowerCase(),t=String(f.type||'').toLowerCase();
 if(/\.svg$/.test(n)||t==='image/svg+xml')return 'svg';if(/\.(png|jpe?g|gif|webp)$/.test(n)||/^image\/(png|jpe?g|gif|webp)$/.test(t))return 'image';if(/\.(xlsx|xls)$/.test(n))return 'sheet';if(/\.csv$/.test(n))return 'csv';if(/\.json$/.test(n))return 'json';if(/\.pdf$/.test(n))return 'pdf';return ''}
function acceptOk(inp,f,k){var a=String(inp.getAttribute('accept')||'').toLowerCase().split(',').map(function(x){return x.trim()}).filter(Boolean);if(!a.length)return !!k;var n=String(f.name||'').toLowerCase(),t=String(f.type||'').toLowerCase();
 return a.some(function(x){return x===t||(x.slice(-2)==='/*'&&t.indexOf(x.slice(0,-1))===0)||(x[0]==='.'&&n.slice(-x.length)===x)||(x==='image/*'&&(k==='image'||k==='svg'))})}
function head(f,n){return new Promise(function(res){var r=new FileReader();r.onload=function(){res(new Uint8Array(r.result))};r.onerror=function(){res(new Uint8Array(0))};r.readAsArrayBuffer(f.slice(0,n))})}
var starts=function(b,s){for(var i=0;i<s.length;i++)if(b[i]!==s[i])return false;return true};
function cleanSvg(txt){try{var d=new DOMParser().parseFromString(txt,'image/svg+xml');if(d.querySelector('parsererror'))return null;
 d.querySelectorAll('script,foreignObject,iframe,object,embed,audio,video').forEach(function(x){x.remove()});
 d.querySelectorAll('*').forEach(function(el){[].slice.call(el.attributes).forEach(function(a){var n=a.name.toLowerCase(),v=String(a.value||'');if(/^on/.test(n)||((n==='href'||n==='xlink:href'||n==='src')&&/^\s*(javascript|data:text\/html)/i.test(v))||(n==='style'&&/expression|javascript:/i.test(v)))el.removeAttribute(a.name)})});
 return new XMLSerializer().serializeToString(d)}catch(e){return null}}
async function vet(inp,f){var k=kindOf(f);if(!k||!acceptOk(inp,f,k))return {err:L('نوع الملف غير مسموح هنا.','This file type is not allowed here.')};
 if(f.size>(MAXB[k]||5*1048576))return {err:L('الملف أكبر من الحد المسموح (','The file exceeds the allowed size (')+Math.round((MAXB[k]||5*1048576)/1048576)+' MB).'};
 if(!f.size)return {err:L('الملف فارغ.','The file is empty.')};
 var b=await head(f,16);
 if(k==='image'){if(!(starts(b,SIG.png)||starts(b,SIG.jpg)||starts(b,SIG.gif)||starts(b,SIG.webp)))return {err:L('محتوى الملف لا يطابق صورة حقيقية.','The file content is not a real image.')}}
 else if(k==='pdf'){if(!starts(b,SIG.pdf))return {err:L('محتوى الملف ليس PDF.','The file content is not a PDF.')}}
 else if(k==='sheet'){if(!(starts(b,SIG.zip)||starts(b,SIG.ole)))return {err:L('محتوى الملف ليس جدول Excel.','The file content is not an Excel workbook.')}}
 else if(k==='json'||k==='csv'){var t=await f.slice(0,2048).text();if(/<\s*script|<\s*html|\u0000/i.test(t))return {err:L('الملف يحوي محتوى غير مسموح.','The file contains disallowed content.')}}
 else if(k==='svg'){var s=await f.text(),c=cleanSvg(s);if(!c)return {err:L('ملف SVG غير صالح.','Invalid SVG file.')};if(c!==s)return {file:new File([c],f.name,{type:'image/svg+xml'})}}
 return {ok:1}}
