try{if(!SVC_ADMIN.some(function(x){return x[0]==='v66d'}))SVC_ADMIN.push(['v66d','إصدار شهادات جماعي دون تسجيل','Bulk certificates without registration'])}catch(e){}
try{if(SET_KEYS.indexOf('batches66')<0)SET_KEYS.push('batches66')}catch(e){}
var BT=function(){var X=S.v51;return X.batches66=X.batches66||[]};
