var opt=function(a,v){return a.map(function(x){return '<option value="'+e6(x[0])+'"'+(String(x[0])===String(v)?' selected':'')+'>'+e6(x[1])+'</option>'}).join('')};
var sexN=function(x){x=String(x||'').trim().toLowerCase();return /^(ذكر|m|male|ذ)$/.test(x)?'ذكر':/^(أنثى|انثى|f|female|ث|أ)$/.test(x)?'أنثى':''};
var key=function(r){return r.sid?'s:'+r.sid:'v:'+String(r.nameAr||'').trim()+'|'+String(r.nameEn||'').trim().toUpperCase()};
/* بيانات الشخص كما ستُطبع (طلاب المعهد من سجلهم) */
function personOf(r){if(r.sid){var s=(S.students||[]).find(function(x){return String(x.id)===String(r.sid)});if(s)return {sid:s.id,name:s.name||'',nameEn:String(s.nameEn||'').trim(),sex:C6.sexOf(s.sex||s.gender),email:s.email||''}}
 return {sid:'',name:String(r.nameAr||'').trim(),nameEn:String(r.nameEn||'').trim().toUpperCase(),sex:C6.sexOf(r.sex||DS.defSex),email:String(r.email||'').trim()}}
function regFor(P,r){var k=key(r);return I.live(I.D().spr).find(function(x){if(x.pid!==P.id)return false;if(r.sid)return String(x.sid)===String(r.sid);var v=x.v||{};return !x.sid&&key({nameAr:v.nameAr,nameEn:v.nameEn})===k})}
/* حالة كل سطر قبل الإصدار */
function stateOf(P,r,ty){var p=personOf(r),m=[];if(!p.name)m.push(L('الاسم بالعربية','Arabic name'));if(!p.nameEn)m.push(L('الاسم بالإنجليزية','English name'));else if(/[؀-ۿ]/.test(p.nameEn))m.push(L('الاسم الإنجليزي بحروف عربية','English name in Arabic letters'));if(!p.sex)m.push(L('الجنس','Gender'));
 if(r.sid&&!(S.students||[]).some(function(x){return String(x.id)===String(r.sid)}))m.push(L('رقم طالب غير موجود','Unknown student ID'));
 if(p.email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(p.email))m.push(L('بريد غير صالح','Invalid email'));
 if(P){var g=regFor(P,r),c=g&&I.issued(g.id);if(c&&!c.revoked)return {k:'issued',rec:c.rec,p:p}}
 var dup=DS.rows.filter(function(x){return key(x)===key(r)}).length>1;if(dup)m.push(L('مكرر في القائمة','Duplicate in the list'));
 return m.length?{k:'miss',m:m,p:p}:{k:'ok',p:p}}
function progMiss(P,ty){if(!P)return [];var PP=Object.assign({},P,{ctype:ty});return C6.missing(PP,{name:'x',nameEn:'X',sex:'m'},I.signers60(C6.TYPES[ty],P))}

