V5.direct66=page;
H.d66cancel=function(id){if(!allowed())return;var b=BT().find(function(x){return x.id===id});if(!b||b.cancelled)return;var why=prompt(L('سبب إلغاء الدفعة كاملة ('+b.n+' شهادة):','Reason for cancelling the whole batch ('+b.n+' certificates):'),'');if(why===null)return;if(!String(why).trim()){toast(L('سبب الإلغاء مطلوب','A reason is required'));return}
 var d=TODAY(),n=0;b.recs.forEach(function(r){var c=S.certs.find(function(x){return x.rec===r});if(c&&!c.revoked){c.revoked=true;c.reason=String(why).trim();c.rdate=d;c.rby=who();c.batchCancel66=b.id;n++;try{touch(c)}catch(e){}}});
 b.cancelled={at:NOW(),by:who(),why:String(why).trim(),n:n};try{V5.setTouch('batches66')}catch(e){}
 try{aud(L('إلغاء دفعة شهادات كاملة (الأرقام محجوزة)','Whole certificate batch cancelled (numbers reserved)'),b.id,L('البرنامج: ','Program: ')+b.pname+' · '+L('عدد الشهادات: ','Certificates: ')+n+' · '+L('السبب: ','Reason: ')+b.cancelled.why+' — '+b.recs.join(', '))}catch(e){}
 save();try{sbQueue()}catch(e){}go();toast(L('أُلغيت الدفعة: ','Batch cancelled: ')+n)};

