H.d66xls=function(el){var file=el.files[0];if(!file)return;var fr=new FileReader(),isCsv=/\.csv$/i.test(file.name);fr.onload=function(){try{var rows;if(isCsv)rows=I.csvRows(new TextDecoder('utf-8').decode(new Uint8Array(fr.result)));else{var wb=XLSX.read(fr.result,{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''})}
  var g=function(o,ks){var k=Object.keys(o).find(function(x){var y=String(x).trim().toLowerCase();return ks.some(function(z){return y===z||y.indexOf(z)===0})});return k?String(o[k]).trim():''};
  addRows(rows.map(function(o){var sid=g(o,['الرقم الأكاديمي','student id','sid']);if(/^\d{9}$/.test(sid))return {sid:sid};
   return {nameAr:g(o,['الاسم بالعربية','arabic name','الاسم']),nameEn:g(o,['الاسم بالإنجليزية','english name','name']).toUpperCase(),sex:sexN(g(o,['الجنس','gender','sex'])),email:g(o,['البريد','email']),phone:g(o,['الجوال','mobile','phone'])}}),'excel')}catch(e){toast(L('تعذر قراءة الملف','Could not read the file'))}el.value=''};fr.readAsArrayBuffer(file)};
H.d66ed=function(i,k,v){var r=DS.rows[i];if(!r)return;r[k]=k==="nameEn"?String(v).trim().toUpperCase():k==="sex"?sexN(v):String(v).trim();go()};
