function batch(){var R=DS.res;return R?R.recs.map(function(r){return S.certs.find(function(c){return c.rec===r})}).filter(function(c){return c&&!c.revoked}):[]}
H.d66zip=function(){var C=batch();if(!C.length)return;if(typeof JSZip==='undefined'){toast('JSZip');return}var o=document.getElementById('d66o'),P=I.progOf(DS.res.pid)||{};
 (async function(){var z=new JSZip();for(var i=0;i<C.length;i++){if(o)o.textContent=(i+1)+' / '+C.length;try{z.file(C[i].rec+'.pdf',await W.mkBlob(certHTML(C[i]),'pdf'))}catch(e){console.error('d66 zip',e)}}
  var b=await z.generateAsync({type:'blob'}),nm='certificates-'+String(P.nameEn||P.id||'batch').replace(/[^A-Za-z0-9]+/g,'-').slice(0,40)+'.zip';try{fsave(nm,b)}catch(e){var a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=nm;a.click()}if(o)o.textContent='';aud(L('تنزيل دفعة شهادات الإصدار المباشر','Direct-issue batch downloaded'),DS.res.pid,String(C.length))})()};
H.d66mail=function(){var C=batch(),P=I.progOf(DS.res&&DS.res.pid);if(!C.length||!P)return;var n=0,no=0;
 C.forEach(function(c){var r=I.regOf(c.spr)||{},p=C6.person(r,S.students),k=C6.KIND_OF[c.type]||P.ctype,T0=C6.TITLES[k]||C6.TITLES.att;if(!p.email){no++;return}
  try{notify(p.email,T0[0]+' — '+P.nameAr+' / '+T0[1]+' — '+P.nameEn,['السلام عليكم '+(p.name||'')+'،','صدرت '+T0[0]+' لـ«'+P.nameAr+'». رقم الشهادة: '+c.rec+'.','Dear '+(p.nameEn||'')+', your '+T0[1]+' for “'+P.nameEn+'” has been issued. Certificate No.: '+c.rec+'.'],c,c.rec);c.mailedAt=NOW();n++}catch(e){}});
 aud(L('إرسال دفعة شهادات الإصدار المباشر بالبريد','Direct-issue batch emailed'),P.id,String(n));save();go();toast(L('أُرسلت: ','Sent: ')+n+(no?L(' · بلا بريد: ',' · no email: ')+no:''))};
