H.pay71cfg=function(f){if(!central())return false;var c=cfg(),v=fv(f),b=JSON.stringify(c);c.wa=String(v.wa||'').trim();c.acctAr=String(v.acctAr||'').trim().slice(0,1500);c.m77=String(v.m77==null?(c.m77||''):v.m77).trim().slice(0,1500);c.acctEn=String(v.acctEn||'').trim().slice(0,1500);c.em=String(v.em||'').trim();c.cur=v.cur||'BDT';c.donate=f.donate.checked?1:0;c.autoMail=f.autoMail.checked?1:0;c.gw={on:f.gwon.checked?1:0,provider:v.gwp||'none',mode:v.gwm||'test'};
 if(c.gw.on&&c.gw.provider==='none'){c.gw.on=0;toast(L('اختر المزوّد قبل تفعيل الدفع المباشر.','Choose a provider before enabling direct payment.'))}touchCfg();try{aud(L('تعديل إعدادات المدفوعات والتبرع','Payment and donation settings edited'),'pay71',b+' → '+JSON.stringify(c))}catch(e){}save();toast(L('حُفظت الإعدادات.','Settings saved.'));go();return false};
